import { useCallback, useEffect, useRef, useState } from 'react'

/**
 * Dictation, using the recogniser that is already on the device.
 *
 * The ask was "Whisper, for free". This is the honest version of that, and the
 * reasoning is worth writing down because the obvious answer is wrong.
 *
 * Running Whisper itself in the browser is possible — WASM builds exist — but
 * the smallest usable model is a 40–75 MB download before the first word is
 * transcribed, fetched from someone else's CDN, on a phone, in Indonesia, quite
 * possibly on mobile data. That is neither free in the sense that matters nor
 * compatible with an app that promises to work offline without fetching
 * anything. `SpeechRecognition` is already installed on the device, costs
 * nothing, starts instantly, and on Android it is the same engine the keyboard's
 * microphone uses — which is to say, the one people already dictate with.
 *
 * The trade is real and the UI says it out loud: on Chrome the audio is sent to
 * Google's speech service to be transcribed. It is opt-in, per press, and only
 * while the button is held on. iOS Safari and recent Android keep it on-device;
 * we cannot detect which, so the copy does not claim either.
 *
 * Nothing is stored by this hook. It hands back text; whether that text is
 * saved is the caller's decision and the user's.
 */

interface RecognitionAlternative {
  transcript: string
}
interface RecognitionResult {
  0: RecognitionAlternative
  isFinal: boolean
  length: number
}
interface RecognitionEvent {
  resultIndex: number
  results: { length: number; [i: number]: RecognitionResult }
}
interface Recognition {
  lang: string
  continuous: boolean
  interimResults: boolean
  maxAlternatives: number
  start(): void
  stop(): void
  abort(): void
  onresult: ((e: RecognitionEvent) => void) | null
  onerror: ((e: { error: string }) => void) | null
  onend: (() => void) | null
}
type RecognitionCtor = new () => Recognition

function ctor(): RecognitionCtor | undefined {
  const w = globalThis as {
    SpeechRecognition?: RecognitionCtor
    webkitSpeechRecognition?: RecognitionCtor
  }
  return w.SpeechRecognition ?? w.webkitSpeechRecognition
}

export type DictationError = 'denied' | 'nospeech' | 'network' | 'other'

export interface Dictation {
  supported: boolean
  listening: boolean
  /** Text confirmed by the recogniser, accumulated across this session. */
  text: string
  /** The words still being revised. Shown greyed so nobody trusts them yet. */
  interim: string
  error: DictationError | null
  start(): void
  stop(): void
  reset(): void
}

export function useDictation(lang = 'id-ID'): Dictation {
  const ref = useRef<Recognition | null>(null)
  const [listening, setListening] = useState(false)
  const [text, setText] = useState('')
  const [interim, setInterim] = useState('')
  const [error, setError] = useState<DictationError | null>(null)
  const supported = !!ctor()

  const stop = useCallback(() => {
    ref.current?.stop()
    setListening(false)
  }, [])

  useEffect(() => {
    // Stopping on unmount matters more here than usual: a live microphone that
    // outlives its screen is the kind of bug people never forgive.
    return () => {
      ref.current?.abort()
      ref.current = null
    }
  }, [])

  const start = useCallback(() => {
    const Ctor = ctor()
    if (!Ctor) return
    setError(null)
    const rec = new Ctor()
    ref.current = rec
    rec.lang = lang
    // Continuous, because the use case is talking while driving — a recogniser
    // that stops after one sentence would be worse than typing.
    rec.continuous = true
    rec.interimResults = true
    rec.maxAlternatives = 1

    rec.onresult = (e) => {
      let settled = ''
      let pending = ''
      for (let i = e.resultIndex; i < e.results.length; i++) {
        const r = e.results[i]
        if (!r) continue
        if (r.isFinal) settled += r[0].transcript
        else pending += r[0].transcript
      }
      if (settled) setText((prev) => (prev ? `${prev} ${settled.trim()}` : settled.trim()))
      setInterim(pending)
    }
    rec.onerror = (e) => {
      setError(
        e.error === 'not-allowed' || e.error === 'service-not-allowed'
          ? 'denied'
          : e.error === 'no-speech'
            ? 'nospeech'
            : e.error === 'network'
              ? 'network'
              : 'other',
      )
      setListening(false)
    }
    // Chrome ends the session on its own after a pause. Reflect that in the
    // button rather than leaving it looking live with a dead microphone.
    rec.onend = () => {
      setInterim('')
      setListening(false)
    }

    try {
      rec.start()
      setListening(true)
    } catch {
      setError('other')
    }
  }, [lang])

  const reset = useCallback(() => {
    setText('')
    setInterim('')
    setError(null)
  }, [])

  return { supported, listening, text, interim, error, start, stop, reset }
}
