/**
 * Cleaning up dictated Indonesian — pure, no React, no recogniser.
 *
 * The device recogniser is good at words and bad at three things that matter
 * for this app specifically. This fixes those three, and nothing else, because
 * a "smart" post-processor that rewrites what someone said is worse than a
 * dumb one that leaves it alone.
 *
 *   1. **Numbers.** Speech comes back as "dua puluh ribu", "seratus lima puluh
 *      ribu", "satu setengah juta". Typing those into a money field by hand is
 *      exactly the friction dictation was supposed to remove.
 *   2. **Punctuation.** There is no way to speak a comma, so people say
 *      "koma" and "titik" and get the words. Spoken punctuation commands are
 *      the one convention every dictation user already knows.
 *   3. **Words this app hears constantly** that general recognisers mangle:
 *      Indomaret, Alfamart, ojol, THR, kondangan, mertua.
 *
 * Everything here is conservative: when a phrase is ambiguous, it is left as
 * spoken. Being wrong in someone's own notes is worse than being literal.
 */

const UNITS: Record<string, number> = {
  nol: 0, kosong: 0, satu: 1, se: 1, dua: 2, tiga: 3, empat: 4, lima: 5,
  enam: 6, tujuh: 7, delapan: 8, sembilan: 9, sepuluh: 10, sebelas: 11,
}

const SCALES: Record<string, number> = { ratus: 100, ribu: 1000, juta: 1_000_000, miliar: 1_000_000_000 }

/**
 * "seratus lima puluh ribu" → 150000.
 *
 * Written as a small state machine rather than a regex table because
 * Indonesian number words compose: `belas` is a suffix, `puluh` and `ratus`
 * multiply what came before, and `ribu`/`juta` close a group and carry it.
 */
export function parseSpokenNumber(words: string[]): number | null {
  let total = 0
  let group = 0
  let current = 0
  let seen = false

  for (const raw of words) {
    const w = raw.toLowerCase()

    if (w in UNITS) {
      current = current === 0 ? UNITS[w]! : current
      if (UNITS[w] !== undefined && current !== UNITS[w]) current = UNITS[w]!
      seen = true
      continue
    }
    if (w.endsWith('belas') && w !== 'belas') {
      const stem = w.slice(0, -5)
      const n = UNITS[stem]
      if (n === undefined) return null
      group += 10 + n
      current = 0
      seen = true
      continue
    }
    if (w === 'belas') {
      group += 10 + current
      current = 0
      seen = true
      continue
    }
    // A multiplier with nothing in front of it is not a number, it is speech
    // noise — "puluh ratus" means nothing. Indonesian spells the one-of forms
    // as sepuluh / seratus / seribu, which are handled separately, so refusing
    // here costs nothing real and stops the parser inventing figures.
    if (w === 'puluh') {
      if (!current) return null
      group += current * 10
      current = 0
      seen = true
      continue
    }
    if (w === 'ratus') {
      if (!current) return null
      group += current * 100
      current = 0
      seen = true
      continue
    }
    if (w === 'ribu' || w === 'juta' || w === 'miliar') {
      if (!group && !current) return null
      total += (group + current) * SCALES[w]!
      group = 0
      current = 0
      seen = true
      continue
    }
    if (w === 'setengah') {
      // Only meaningful attached to a scale: "satu setengah juta".
      group += 0.5
      seen = true
      continue
    }
    // Prefixed forms: seratus, seribu, sejuta, sepuluh handled above.
    if (w.startsWith('se') && w.slice(2) in SCALES) {
      const scale = SCALES[w.slice(2)]!
      if (scale === 100) {
        group += 100
      } else {
        total += (group + current || 1) * scale
        group = 0
        current = 0
      }
      seen = true
      continue
    }
    return null
  }

  if (!seen) return null
  const n = total + group + current
  return n > 0 ? Math.round(n) : null
}

/** Turns runs of number words inside a sentence into digits. */
export function digitsFromWords(text: string): string {
  // `belas` is listed on its own as well as suffixed: the recogniser returns
  // "lima belas" as two words at least as often as "limabelas", and leaving
  // the bare form out broke the run in the middle of a number.
  const NUMBER_WORD =
    /^(nol|kosong|satu|dua|tiga|empat|lima|enam|tujuh|delapan|sembilan|sepuluh|sebelas|belas|[a-z]+belas|puluh|ratus|ribu|juta|miliar|seratus|seribu|sejuta|setengah)$/i

  const out: string[] = []
  let run: string[] = []

  const flush = () => {
    if (!run.length) return
    const n = parseSpokenNumber(run)
    // Left as spoken when it does not parse — a half-understood number written
    // as digits is a wrong number in someone's book.
    out.push(n === null ? run.join(' ') : String(n))
    run = []
  }

  for (const tok of text.split(/\s+/).filter(Boolean)) {
    const bare = tok.replace(/[.,!?;:]+$/, '')
    const trail = tok.slice(bare.length)
    if (NUMBER_WORD.test(bare)) {
      run.push(bare)
      if (trail) {
        flush()
        out.push(trail)
      }
      continue
    }
    flush()
    out.push(tok)
  }
  flush()
  // Joined with single spaces, then the punctuation is pulled back onto the
  // word it belongs to.
  return out.join(' ').replace(/\s+([.,;:?!])/g, '$1').trim()
}

/** Spoken punctuation, the one dictation convention everybody already knows. */
export function applyPunctuation(text: string): string {
  return text
    .replace(/\s*\b(titik dua)\b\s*/gi, ': ')
    .replace(/\s*\b(titik koma)\b\s*/gi, '; ')
    .replace(/\s*\b(baris baru|ganti baris|enter)\b\s*/gi, '\n')
    .replace(/\s*\b(koma)\b\s*/gi, ', ')
    .replace(/\s*\b(titik)\b\s*/gi, '. ')
    .replace(/\s*\b(tanda tanya)\b\s*/gi, '? ')
    .replace(/\s*\b(tanda seru)\b\s*/gi, '! ')
    .replace(/\s+([.,;:?!])/g, '$1')
    .replace(/[ \t]{2,}/g, ' ')
    .trim()
}

/**
 * Words this app hears all day that general recognisers get wrong.
 *
 * Deliberately short. Every entry is a term that comes up in household and
 * money notes, spelled the way the recogniser actually returns it.
 */
const FIXES: [RegExp, string][] = [
  [/\bindo maret\b/gi, 'Indomaret'],
  [/\balfa mart\b/gi, 'Alfamart'],
  [/\bgo jek\b/gi, 'Gojek'],
  [/\bgrap\b/gi, 'Grab'],
  [/\bo jol\b/gi, 'ojol'],
  [/\bte ha er\b/gi, 'THR'],
  [/\bka pe er\b/gi, 'KPR'],
  [/\bpe de am\b/gi, 'PDAM'],
  [/\bbe pe je es\b/gi, 'BPJS'],
  [/\bmertuah\b/gi, 'mertua'],
  [/\bkondangan\b/gi, 'kondangan'],
  [/\bar te\b/gi, 'ART'],
]

export function fixTerms(text: string): string {
  let out = text
  for (const [re, to] of FIXES) out = out.replace(re, to)
  return out
}

/** Sentence case, without touching anything already capitalised. */
export function tidy(text: string): string {
  const t = text.replace(/\s+/g, ' ').trim()
  if (!t) return t
  return t
    .split(/(?<=[.!?]\s)/)
    .map((s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s))
    .join('')
}

/** The whole pass, in the order the steps depend on each other. */
export function cleanDictation(raw: string): string {
  // Punctuation first: "dua koma lima" must become "dua, lima" before the
  // number pass sees it, or it is read as one number.
  return tidy(fixTerms(digitsFromWords(applyPunctuation(raw))))
}
